        foreach(var (slotID,sourceID) in new[]{(1,0),(2,1)}){var bytes=targetAnims.Files.Single(f=>f.ID==1000000000+slotID).Bytes.ToArray();var pack=new NativeAnimation.Pack(bytes);int a=pack.Object("hkaSplineCompressedAnimation");var data=pack.Array(a+152,1,1000000);var tracks=SplineCompressedAnimation.ReadSplineCompressedAnimByteBlock(false,bytes.AsSpan(pack.Data+data.At,data.Count).ToArray(),2,1).Single();var clip=SourceAnimation.Decode(sourceAnims.Files.Single(f=>f.ID==1000000).Bytes.ToArray(),sourceAnims.Files.Single(f=>f.ID==sourceID).Bytes.ToArray());var bone=clip.Bones[2];var local=Matrix4x4.CreateScale(bone.Scale)*Matrix4x4.CreateFromQuaternion(bone.Rotation)*Matrix4x4.CreateTranslation(bone.Translation);Check(Matrix4x4.Invert(local,out var inverse),"singular source leaf");Check(pack.Int(a+56)==61&&Math.Abs(pack.Float(a+16)-2)<.000001f,"source timing lost");foreach(int f in new[]{0,10,30,50,60}){var expected=rig.Local[1]*inverse*clip.Sample(f/30f)[2];var actual=Track(tracks[1],f);foreach(var point in points)motionError=Math.Max(motionError,Vector3.Distance(Vector3.Transform(point,expected),Vector3.Transform(point,actual)));}}Check(motionError<.002f,"native motion/collision corners disagree with actual source swing");
